import { expect, test, uniqueName } from "../../fixtures";

test.describe("REV-02 submit vendor with missing documents", () => {
  test(
    "submitting with only a w9 lists contract and insurance_certificate as missing",
    { tag: "@REV-02" },
    async ({ apiAs }) => {
      // Arrange: a signed-in member, a draft vendor, and one extracted w9 document.
      const member = await apiAs("member");

      const vendorResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("REV02 Vendor"),
          category: "services",
          contact_email: `ops.${Date.now().toString(36)}@rev02.example.test`,
        },
      });
      expect(vendorResponse.status()).toBe(201);
      const vendor = await vendorResponse.json();
      expect(vendor.status).toBe("draft");

      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.pdf",
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4 REV-02 w9 sample"),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);
      const document = await uploadResponse.json();

      // Wait for extraction to finish so the w9 is in the "extracted" state.
      await expect
        .poll(
          async () => {
            const res = await member.get(`/api/documents/${document.id}`);
            return ((await res.json()) as { status: string }).status;
          },
          { timeout: 60_000, intervals: [500, 1000, 2000] },
        )
        .toBe("extracted");

      // Act
      const response = await member.post(`/api/vendors/${vendor.id}/submit`);

      // Assert
      expect(response.status()).toBe(409);
      const body = await response.json();
      expect(body.error.code).toBe("documents_incomplete");

      const serialized = JSON.stringify(body);
      expect(serialized).toContain("contract");
      expect(serialized).toContain("insurance_certificate");
    },
  );
});
